'use client';

import { useEffect, useRef } from 'react';

type SectionId = 'about' | 'projects' | 'art' | 'photos' | 'contact';

// ─── Minimal type stubs for the dynamically-loaded p5 global ──────────────────
interface P5Vector {
  x: number;
  y: number;
  z: number;
  copy(): P5Vector;
  mult(scalar: number): void;
  add(v: P5Vector): void;
}

interface P5Canvas {
  style(prop: string, value: string): void;
}

interface P5Image {
  width: number;
  height: number;
  loadPixels(): void;
  pixels: number[];
}

interface P5 {
  setup: () => void;
  draw: () => void;
  windowResized: () => void;

  width: number;
  height: number;
  windowWidth: number;
  windowHeight: number;
  mouseX: number;
  mouseY: number;
  frameCount: number;

  TWO_PI: number;
  PI: number;
  CLOSE: string;

  createCanvas(w: number, h: number): P5Canvas;
  resizeCanvas(w: number, h: number): void;
  loadImage(src: string, cb: (img: P5Image) => void): void;
  noStroke(): void;
  stroke(r: number, g: number, b: number, a?: number): void;
  strokeWeight(w: number): void;
  fill(v1: number, v2?: number, v3?: number, v4?: number): void;
  noFill(): void;
  rect(x: number, y: number, w: number, h: number): void;
  ellipse(x: number, y: number, d: number): void;
  line(x1: number, y1: number, x2: number, y2: number): void;
  push(): void;
  pop(): void;

  noise(x: number, y: number, z: number): number;
  sin(angle: number): number;
  cos(angle: number): number;
  tan(angle: number): number;
  random(min: number, max?: number): number;
  map(value: number, start1: number, stop1: number, start2: number, stop2: number): number;
  constrain(v: number, lo: number, hi: number): number;
  lerp(a: number, b: number, t: number): number;
  dist(x1: number, y1: number, x2: number, y2: number): number;
  floor(n: number): number;
  sqrt(n: number): number;

  createVector(x: number, y: number, z?: number): P5Vector;
}

interface P5Constructor {
  new (sketch: (p: P5) => void, container: HTMLElement): { remove(): void };
}

interface RepelZone {
  x: number;
  y: number;
  r: number;
  force: number;
}

// ─── Section → numeric mode ───────────────────────────────────────────────────
const SECTION_MODE: Record<SectionId, number> = {
  about:    0,
  contact:  0,
  projects: 1,
  art:      2,
  photos:   3,
};

// ─── Bitmap images for art mode ───────────────────────────────────────────────
// Replace each PLACEHOLDER with output of:
//   base64 -i your-image.png | tr -d '\n' | pbcopy
// then paste after "data:image/png;base64,"
const BITMAP_SRCS: string[] = [
  'data:image/png;base64,',
  'data:image/jpeg;base64,',
  'data:image/jpeg;base64,',
  'data:image/jpeg;base64,',
  'data:image/jpeg;base64,',
];

// Where each shape sits on screen as 0–1 fractions of viewport (cx, cy)
const SHAPE_ANCHORS: [number, number][] = [
  [0.18, 0.30],
  [0.55, 0.20],
  [0.80, 0.55],
  [0.35, 0.72],
  [0.70, 0.80],
];

const SAMPLE_STEP = 4;   // sample every N pixels — lower = denser shapes
const SHAPE_SCALE = 0.7; // scale factor on sampled coords

declare global {
  interface Window { p5: P5Constructor; }
}

interface BackgroundCanvasProps {
  activeSection?: SectionId | null;
}

export default function BackgroundCanvas({ activeSection }: BackgroundCanvasProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  // Mutable ref — sketch reads this every frame, zero re-renders
  const sectionRef = useRef<number>(0);

  useEffect(() => {
    sectionRef.current = SECTION_MODE[activeSection ?? 'about'] ?? 0;
  }, [activeSection]);

  useEffect(() => {
    let p5Instance: { remove(): void } | undefined;
    let cancelled = false;

    function init() {
      if (cancelled) return;
      if (!window.p5) { setTimeout(init, 50); return; }

      const P5 = window.p5;

      const sketch = (p: P5) => {

        // ── original config — kept exactly as your file ────────────────
        const num           = 900;
        const noiseScale    = 100;
        const noiseStrength = 1;

        // ── repulsion config — kept exactly as your file ───────────────
        const MOUSE_RADIUS = 120;
        const MOUSE_FORCE  = 6;
        const DOM_RADIUS   = 80;
        const DOM_FORCE    = 4;

        // How fast particles morph between section modes (~100 frames full transition)
        const LERP_SPEED = 0.010;

        const particles: Particle[] = new Array(num);
        let repelZones: RepelZone[] = [];
        let zoneTimer = 0;
        let bgAlpha = 10;

        // ── Glitch bands for projects (retro TV effect) ────────────────
        let glitchBands: Array<{ y: number; h: number; shift: number; life: number }> = [];
        let glitchTimer = 0;
        const GLITCH_INTERVAL = 40;
        const GLITCH_BAND_LIFE = 10;

        // Point clouds per shape — populated after images load
        const shapeClouds: { x: number; y: number }[][] = BITMAP_SRCS.map(() => []);
        let imagesLoaded = 0;

        // ── Sample a loaded image into screen-space points ─────────────
        function sampleImage(img: P5Image, idx: number) {
          const cloud: { x: number; y: number }[] = [];
          img.loadPixels();
          const [anchorX, anchorY] = SHAPE_ANCHORS[idx];
          const cx   = anchorX * p.width;
          const cy   = anchorY * p.height;
          const offX = (img.width  * SHAPE_SCALE) / 2;
          const offY = (img.height * SHAPE_SCALE) / 2;

          for (let y = 0; y < img.height; y += SAMPLE_STEP) {
            for (let x = 0; x < img.width; x += SAMPLE_STEP) {
              const i          = (y * img.width + x) * 4;
              const brightness = (img.pixels[i] + img.pixels[i + 1] + img.pixels[i + 2]) / 3;
              if (img.pixels[i + 3] > 128 && brightness < 100) {
                cloud.push({
                  x: cx - offX + x * SHAPE_SCALE,
                  y: cy - offY + y * SHAPE_SCALE,
                });
              }
            }
          }
          shapeClouds[idx] = cloud;
        }

        function loadAllImages() {
          imagesLoaded = 0;
          BITMAP_SRCS.forEach((src, idx) => {
            p.loadImage(src, (img: P5Image) => {
              sampleImage(img, idx);
              imagesLoaded++;
              if (imagesLoaded === BITMAP_SRCS.length) {
                for (let i = 0; i < num; i++) particles[i].assignTarget();
              }
            });
          });
        }

        // ── Repel zones ────────────────────────────────────────────────
        function refreshRepelZones() {
          repelZones = [];
          document.querySelectorAll('[data-repel]').forEach((el) => {
            const rect = el.getBoundingClientRect();
            const cx   = rect.left + rect.width  / 2;
            const cy   = rect.top  + rect.height / 2;
            const r    = Math.sqrt(rect.width ** 2 + rect.height ** 2) / 2 + DOM_RADIUS;
            repelZones.push({ x: cx, y: cy, r, force: DOM_FORCE });
          });
        }

        // ── Particle class ─────────────────────────────────────────────
        class Particle {
          loc:   P5Vector;
          dir:   P5Vector;
          speed: number;
          blend: number; // float 0–3 tracking current mode

          seed:         number;
          glitchOffset: number;
          dustDx:       number;
          dustDy:       number;

          shapeIndex: number;
          targetX:    number;
          targetY:    number;

          constructor(_loc: P5Vector, _dir: P5Vector, _speed: number, index: number) {
            this.loc   = _loc;
            this.dir   = _dir;
            this.speed = _speed;
            this.blend = sectionRef.current;

            this.seed         = p.random(1000);
            this.glitchOffset = p.random(p.TWO_PI);
            this.dustDx       = p.random(-0.3, 0.3);
            this.dustDy       = p.random(-0.12, 0.12);

            this.shapeIndex = index % BITMAP_SRCS.length;
            this.targetX    = p.random(p.width);
            this.targetY    = p.random(p.height);
          }

          assignTarget() {
            const cloud = shapeClouds[this.shapeIndex];
            if (cloud.length === 0) return;
            const pt     = cloud[p.floor(p.random(cloud.length))];
            this.targetX = pt.x;
            this.targetY = pt.y;
          }

          run() {
            this.blend += (sectionRef.current - this.blend) * LERP_SPEED;
            this.move();
            this.checkEdges();
            this.update();
          }

          move() {
            const b = this.blend;

            // ── Mode 0: about — original OG noise flow ─────────────────
            const angle = p.noise(
              this.loc.x / noiseScale,
              this.loc.y / noiseScale,
              p.frameCount / noiseScale,
            ) * p.TWO_PI * noiseStrength;

            this.dir.x = p.sin(angle);
            this.dir.y = p.tan(angle);

            const vel = this.dir.copy();
            vel.mult(this.speed * 22);

            // ── Mode 1: projects — retro TV static, particles nearly stationary ──
            const projDx = this.dustDx * 0.25;
            const projDy = this.dustDy * 0.15;

            // ── Mode 2: art — drift toward bitmap target ───────────────
            const artStrength = p.constrain(b - 1, 0, 1) * 0.045;
            const artDx = (this.targetX - this.loc.x) * artStrength;
            const artDy = (this.targetY - this.loc.y) * artStrength;

            // ── Mode 3: photos — ultra slow dust drift ─────────────────
            const photoDx = this.dustDx;
            const photoDy = this.dustDy;

            // Blend movement between adjacent modes
            let dx: number, dy: number;
            if (b < 1) {
              const t = p.constrain(b, 0, 1);
              dx = p.lerp(vel.x, projDx, t);
              dy = p.lerp(vel.y, projDy, t);
            } else if (b < 2) {
              const t = p.constrain(b - 1, 0, 1);
              dx = p.lerp(projDx, artDx, t);
              dy = p.lerp(projDy, artDy, t);
            } else {
              const t = p.constrain(b - 2, 0, 1);
              dx = p.lerp(artDx, photoDx, t);
              dy = p.lerp(artDy, photoDy, t);
            }

            this.loc.x += dx;
            this.loc.y += dy;

            // ── mouse repulsion — about section only ───────────────────
            const aboutWeight = p.constrain(1 - this.blend, 0, 1);
            if (aboutWeight > 0.01) {
              const mdx = this.loc.x - p.mouseX;
              const mdy = this.loc.y - p.mouseY;
              const md  = Math.sqrt(mdx * mdx + mdy * mdy);
              if (md < MOUSE_RADIUS && md > 0) {
                const strength = (1 - md / MOUSE_RADIUS) * MOUSE_FORCE * aboutWeight;
                this.loc.x += (mdx / md) * strength * this.speed * 2;
                this.loc.y += (mdy / md) * strength * this.speed * 2;
              }
            }

            // ── DOM repulsion — from your original file ────────────────
            for (const zone of repelZones) {
              const zdx = this.loc.x - zone.x;
              const zdy = this.loc.y - zone.y;
              const zd  = Math.sqrt(zdx * zdx + zdy * zdy);
              if (zd < zone.r && zd > 0) {
                const strength = (1 - zd / zone.r) * zone.force;
                this.loc.x += (zdx / zd) * strength * this.speed * 2;
                this.loc.y += (zdy / zd) * strength * this.speed * 2;
              }
            }
          }

          checkEdges() {
            // Art mode: particles have targets, don't teleport them
            const inArt = this.blend > 1.2 && this.blend < 2.8;
            if (inArt) return;
            if (
              this.loc.x < 0 || this.loc.x > p.width ||
              this.loc.y < 0 || this.loc.y > p.height
            ) {
              // Projects mode: respawn on-screen for TV static coverage
              const inProjects = this.blend > 0.3 && this.blend < 1.7;
              if (inProjects) {
                this.loc.x = p.random(p.width);
                this.loc.y = p.random(p.height);
              } else {
                this.loc.x = p.random(p.width * 10);
                this.loc.y = p.random(p.height);
              }
            }
          }

          update() {
            const b = this.blend;

            // Mode 0: about — your exact original color (240, 240, 255)
            const aboutW = p.constrain(1 - b, 0, 1);
            if (aboutW > 0.01) {
              p.noStroke();
              p.fill(240, 240, 255, 255 * aboutW);
              p.ellipse(this.loc.x, this.loc.y, this.loc.z);
            }

            // Mode 1: projects — retro TV static, glitch in place
            const projW = b < 1
              ? p.constrain(b, 0, 1)
              : p.constrain(2 - b, 0, 1);
            if (projW > 0.01) {
              // Find glitch band displacement for this particle's Y
              let xShift = 0;
              let bandLife = 0;
              for (const band of glitchBands) {
                if (this.loc.y >= band.y && this.loc.y < band.y + band.h) {
                  xShift = band.shift * (band.life / GLITCH_BAND_LIFE);
                  bandLife = band.life;
                  break;
                }
              }
              const drawX = this.loc.x + xShift;
              const drawY = this.loc.y;
              // Random flicker like TV static
              const flicker = Math.random() > 0.12 ? p.random(0.3, 1.0) : 0;
              p.noStroke();
              p.fill(240, 240, 255, 255 * projW * flicker);
              p.ellipse(drawX, drawY, p.random(0.5, 2.5));
              // Short horizontal dash in active glitch bands
              if (bandLife > 0 && flicker > 0) {
                p.stroke(240, 240, 255, 200 * projW * flicker);
                p.strokeWeight(0.5);
                p.line(drawX, drawY, drawX + p.random(4, 18), drawY);
                p.noStroke();
              }
            }

            // Mode 2: art — tiny dot, forms bitmap shape
            const artW = b < 2
              ? p.constrain(b - 1, 0, 1)
              : p.constrain(3 - b, 0, 1);
            if (artW > 0.01) {
              p.noStroke();
              const dotSize = p.lerp(0.8, 2.0, artW) +
                Math.sin(p.frameCount * 0.04 + this.seed) * 0.3;
              p.fill(240, 240, 255, 255 * artW);
              p.ellipse(this.loc.x, this.loc.y, dotSize);
            }

            // Mode 3: photos — faint random-size grain
            const photoW = p.constrain(b - 2, 0, 1);
            if (photoW > 0.01) {
              p.noStroke();
              p.fill(240, 240, 255, 255 * photoW * p.random(0.3, 0.9));
              p.ellipse(this.loc.x, this.loc.y, p.random(0.5, 2.0));
            }
          }
        }

        // ── setup — kept exactly as your file ──────────────────────────
        p.setup = () => {
          const cnv = p.createCanvas(p.windowWidth, p.windowHeight);
          cnv.style('position', 'fixed');
          cnv.style('top', '0');
          cnv.style('left', '0');
          cnv.style('z-index', '-2');
          cnv.style('pointer-events', 'none');
          p.noStroke();

          for (let i = 0; i < num; i++) {
            const loc   = p.createVector(p.random(p.width * 1.2), p.random(p.height), 2);
            const angle = 0;
            const dir   = p.createVector(p.cos(angle), p.sin(angle));
            const speed = p.random(5, p.map(p.mouseX, 0, p.width, 5, 20));
            particles[i] = new Particle(loc, dir, speed, i);
          }

          refreshRepelZones();
          loadAllImages();
        };

        p.windowResized = () => {
          p.resizeCanvas(p.windowWidth, p.windowHeight);
          refreshRepelZones();
          loadAllImages(); // re-sample so shape anchors use new dimensions
        };

        // ── draw — kept exactly as your file ───────────────────────────
        p.draw = () => {
          // Background alpha: more opaque in art mode to kill trails
          const targetBgAlpha = sectionRef.current === 2 ? 80 : 10;
          bgAlpha += (targetBgAlpha - bgAlpha) * 0.03;
          p.fill(0, bgAlpha);
          p.rect(0, 0, p.width, p.height);

          // Projects mode: retro TV glitch bands + scanlines
          if (sectionRef.current === 1) {
            glitchTimer++;
            if (glitchTimer >= GLITCH_INTERVAL || Math.random() > 0.985) {
              glitchTimer = 0;
              const count = Math.floor(Math.random() * 3) + 1;
              for (let k = 0; k < count; k++) {
                glitchBands.push({
                  y: Math.random() * p.height,
                  h: Math.random() * 50 + 8,
                  shift: (Math.random() - 0.5) * 140,
                  life: GLITCH_BAND_LIFE,
                });
              }
            }
            glitchBands = glitchBands.filter((band) => { band.life--; return band.life > 0; });
            // Scanline overlay
            if (Math.sin(p.frameCount * 0.05) > 0.92) {
              p.fill(240, 240, 255, p.random(8, 22));
              p.rect(0, p.random(p.height), p.width, p.random(2, 18));
            }
          } else {
            glitchBands = [];
            glitchTimer = 0;
          }

          zoneTimer++;
          if (zoneTimer >= 30) {
            refreshRepelZones();
            zoneTimer = 0;
          }

          for (let i = 0; i < particles.length; i++) {
            particles[i].run();
          }
        };
      };

      if (containerRef.current) {
        p5Instance = new P5(sketch, containerRef.current);
      }
    }

    init();

    return () => {
      cancelled = true;
      if (p5Instance) p5Instance.remove();
    };
  }, []);

  return (
    <div
      ref={containerRef}
      style={{ position: 'fixed', top: 0, left: 0, width: 0, height: 0, zIndex: -2 }}
    />
  );
}